const followingKey='slice-following-v1';const followedData=readStored(followingKey,[]);let followedAuthors=new Set(Array.isArray(followedData)?followedData.filter(x=>typeof x==='string'):[]);
const followingDialog=document.createElement('dialog');followingDialog.id='following-dialog';followingDialog.setAttribute('aria-labelledby','following-title');document.body.append(followingDialog);
const followingPage=document.createElement('main');followingPage.id='following-page';followingPage.hidden=true;document.querySelector('main#discover').after(followingPage);
function setFollows(next){try{localStorage.setItem(followingKey,JSON.stringify([...next]))}catch{toast('Could not save your follows. Check browser storage.');return false}followedAuthors=next;renderFollowingFeed();return true}
function renderFollowing(){const creators=[...new Set(works.map(w=>w.author))];followingDialog.innerHTML=`<div class="dialog-head"><span>YOUR SLICERS</span><button data-close-following aria-label="Close follow manager">✕</button></div><h2 id="following-title">Manage follows</h2><p>Follow creators to find their playable experiences in your feed.</p><div class="following-creators">${creators.map((a,i)=>`<article><span class="following-avatar">${escapeHtml(a.slice(0,1))}</span><div><strong>${escapeHtml(a)}</strong><small>${works.filter(w=>w.author===a).length} Slices · ${escapeHtml(works.find(w=>w.author===a).cat)}</small></div><button data-follow-index="${i}" aria-pressed="${followedAuthors.has(a)}">${followedAuthors.has(a)?'Following ✓':'＋ Follow'}</button></article>`).join('')}</div>`;followingDialog.querySelectorAll('[data-follow-index]').forEach(b=>b.onclick=()=>{const a=creators[+b.dataset.followIndex],next=new Set(followedAuthors);next.has(a)?next.delete(a):next.add(a);if(setFollows(next))renderFollowing()})}
function renderFollowingFeed(){const list=works.filter(w=>followedAuthors.has(w.author));followingPage.innerHTML=`<div class="following-page-heading"><div><span class="eyebrow">YOUR SLICERS, THEIR SLICES</span><h1>Slicers</h1><p>Playable discoveries from the creators you follow.</p></div><button data-manage-following>Manage follows <span>${followedAuthors.size}</span></button></div><div class="following-feed-layout"><section class="following-stream" aria-label="Following feed">${list.length?list.map(w=>`<article class="card following-feed-card"><div class="following-byline"><span class="following-avatar">${escapeHtml(w.author.slice(0,1))}</span><div><strong>${escapeHtml(w.author)}</strong><small>${escapeHtml(w.time)} · ${escapeHtml(w.cat)}</small></div><span>Following</span></div><h3>${escapeHtml(w.title)}</h3><p>${escapeHtml(w.desc)}</p>${stage(w)}<div class="card-actions"><button data-like="${w.id}" class="${likes.has(w.id)?'liked':''}" aria-pressed="${likes.has(w.id)}" aria-label="Like ${escapeHtml(w.title)}">${likes.has(w.id)?'♥':'♡'} ${w.likes+(likes.has(w.id)?1:0)}</button><button data-share="${w.id}">↗ Share</button><button data-remix="${w.id}">⤨ Remix</button><button data-save="${w.id}" aria-pressed="${libraryIds.has(w.id)}">${libraryIds.has(w.id)?'✓ Saved':'＋ Library'}</button><button data-open="${w.id}">Play Slice ↗</button></div></article>`).join(''):'<div class="following-feed-empty"><span>✳</span><h2>Start by following a Slicer.</h2><p>Their interactive experiences will appear here, ready to play and save.</p><button class="dark" data-manage-following>Discover Slicers →</button><button data-demo-following>Try a demo following feed</button></div>'}</section><aside class="following-feed-aside"><h3>Slicers you follow</h3>${[...followedAuthors].map(a=>`<div class="followed-person"><span class="following-avatar">${escapeHtml(a.slice(0,1))}</span><span>${escapeHtml(a)}</span></div>`).join('')||'<p>You are not following any Slicers yet.</p>'}<button data-manage-following>Find more Slicers ＋</button><p class="following-local-note">Prototype content. Your follows are saved locally. Cross-device sync is not connected yet.</p></aside></div>`;initStages(followingPage)}
function showFollowing(){document.querySelector('main#discover').hidden=true;followingPage.hidden=false;renderFollowingFeed();document.querySelectorAll('header nav a').forEach(a=>{a.classList.toggle('current',a.id==='following-link');if(a.id==='following-link')a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')})}
function syncFollowingRoute(){if(location.hash==='#following')showFollowing();else{followingPage.hidden=true;document.querySelector('main#discover').hidden=false;document.querySelectorAll('header nav a').forEach(a=>{const current=a.getAttribute('href')===(location.hash==='#trending'?'#trending':'#discover');a.classList.toggle('current',current);if(current)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')})}}
document.querySelector('#following-link').onclick=e=>{e.preventDefault();if(location.hash==='#following')showFollowing();else location.hash='following';window.scrollTo({top:0,behavior:'smooth'})};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-manage-following')){renderFollowing();followingDialog.showModal()}if(b.hasAttribute('data-close-following'))followingDialog.close();if(b.hasAttribute('data-demo-following')){setFollows(new Set([...followedAuthors,'Studio Small','Form & Play','Kepler Lab']));toast('Following 3 demo creators. Change them in Manage follows.')}});
const beforeFollowingRender=render;render=function(){beforeFollowingRender();if(!followingPage.hidden)renderFollowingFeed()};
window.addEventListener('hashchange',syncFollowingRoute);syncFollowingRoute();
